package mocks

// HoldsNoRetiredBookFiles declares the generated MockStore a store that never
// holds a retired book_file row (database.NoRetiredBookFiles), so the
// database.*IncludingRetired helpers answer from its plain, expectation-driven
// reads instead of failing closed. It lives in its own file because mock_store.go
// is regenerated by mockery; the file name still ends in mock_store.go so the
// unreachable-function ratchet (scripts/deadcode-ratchet.py) exempts it like the
// rest of the mock's methods.
func (*MockStore) HoldsNoRetiredBookFiles() bool { return true }
